csui.define('csui/utils/proxy',['module'],
  function (module) {
  "use strict";

  var _proxyEnabled = module.config().enabled || false;
  var _limitPerUser = module.config().limitPerUser || 15;

  var Proxy = {

    enabled: function(){
      return _proxyEnabled;
    },

    limitPerUser: function (){
      return _limitPerUser;
    }
  };

  return Proxy;

});