csui.define('csui/controls/mixins/dynamic.toolitems/reopening.toolbar.mixin',[
  'module',
  'csui/lib/jquery',
  'nuc/lib/underscore',
  'nuc/utils/log',
], function (module, $, _, log) {
  'use strict';

  log = log(module.id);

  var ToolbarReopenMixin = {
    mixin: function (prototype) {
      return _.extend(prototype, {
        makeReopeningToolbar: function (options) {
          this.listenTo(this.collection, 'before:reset remain', this._initReopenAfterAdjust);
        },

        /**
         * check if dropdown or a submenu is open before reset and ensure to reopen it afterwards.
         * to be called when the events 'before:reset' or 'remain' are triggered on the filterd toolitems collection.
         * 'this' must be bound to the actual toolbarview.
         */
        _initReopenAfterAdjust: function(collection, { models } = {}) {

          var opened, dropdown;
          var afterAdjustEvent = this.options.afterAdjustEvent || 'after:adjust';

          // only needed if reset does not result in empty toolbar.
          if (models && models.length > 0) {

            // check submenu.
            this.children.find(child => {
              if (child.model.get('name') && child.el.matches('.binf-dropdown-submenu.binf-open')) {
                // object with name indicates to reopen submenu.
                opened = child.model.pick('name')
                return true;
              }
            });
            // check dropdown.
            dropdown = this.el.querySelector('ul > li.binf-dropdown')
            if (dropdown && dropdown.classList.contains('binf-open')) {
              // object with dropdown flag indicates to reopen dropdown.
              opened = (opened || {});
              opened.dropdown = true;
            }

            if (opened) {
              // reopen only after next render.
              this.listenToOnce(this, afterAdjustEvent, reopenToolItem);
            }
          }

          function reopenToolItem() {

            // in case we are registered for multiple events, deregister for all others
            this.stopListening(this, afterAdjustEvent, reopenToolItem);

            // find the submenu to reopen.
            var subitem = opened.name && this.children.find(child => {
              return child.model.get('name') === opened.name && child.el.classList.contains('binf-dropdown-submenu');
            });

            // reopen dropdown, if needed.
            var dropdown = this.el.querySelector('ul > li.binf-dropdown');
            if (dropdown && !dropdown.classList.contains('binf-open')) {
              if (subitem ? dropdown.contains(subitem.el) : opened.dropdown) {
                // binf_dropdown('toggle') does not seem to work. Manually toggle it.
                var dropdownToggler = this.$el.find('li.binf-dropdown > a.binf-dropdown-toggle');
                dropdownToggler.trigger('binf.dropdown.before.show');
                dropdown.classList.add('binf-open');
                dropdownToggler.attr('aria-expanded', 'true');
                dropdownToggler.trigger('binf.dropdown.after.show');
              }
            }

            // reopen submenu, if needed.
            if (subitem && !subitem.el.classList.contains('binf-open')) {
              // we need to pass an event to show() to avoid binf focusing on the first menu item,
              // but with the usual call $el.binf_dropdown_submenu('show') we cannot do that.
              subitem.$el.binf_dropdown_submenu().data('binf.dropdown.submenu').show($.Event('click', { which: 1 }));
            }
          }
        }

      });
    }
  };

  return ToolbarReopenMixin;
});
